27: // TiffExporter.hpp
28: // ================
29: // The classes in this file are used to read TIFF pixel data in various formats
30: // and copy them to a simple flat-buffer of 8, 16, or 32 bits per channel. This
31: // pre-processing step can be useful for converting TIFF images into a more
32: // manageable format for further processing or analysis.
33: //
34: // Code like the following could be used to read TIFF images and get a copy of
35: // their pixel data in a flat buffer:
36: //
37: //     #include <tiffcraft/TiffExporter.hpp>
38: //     #include <functional>
39: //
40: //     int main(int argc, char* argv[]) {
41: //       if (argc < 2) { return 1; }
42: //       TiffCraft::TiffExporterAny tiffExporter;
43: //       TiffCraft::load(argv[1], std::ref(tiffExporter));
44: //       auto image = tiffExporter.takeImage();
45: //
46: //       // your own image processing code
47: //
48: //       return 0;
49: //     }
50: //
