436:             bitsAvail = 0;
437:           }
438:         }
439:       };
440: 
441:       auto process_word = [&]() -> DstType {
442:         DstType value = *reinterpret_cast<const SrcType*>(&(*srcRow));
443:         srcRow += sizeof(SrcType);
444:         if (!equalsHostByteOrder) {
445:           value = swap(value);
446:         }
447:         return value;
448:       };
449: 
450:       auto process_bits = [&]() -> DstType {
451:         size_t count = 0;
452:         DstType value = 0;
453:         while (count < rectInfo.bitsPerSample) {
454:           // make sure we have some bits available
455:           if (countAvail == 0) {
456:             bitsAvail = *reinterpret_cast<const SrcType*>(&(*srcRow));
457:             srcRow += sizeof(SrcType);
458:             if (!equalsHostByteOrder) {
459:               bitsAvail = swap(bitsAvail);
460:             }
461:             countAvail = bitsPerSrcPixel;
462:           }
463:           // consume available bits
464:           const size_t n = std::min(rectInfo.bitsPerSample - count, countAvail);
465:           value <<= n;
466:           value |= (bitsAvail >> (bitsPerSrcPixel - n));
467:           count += n;
468:           // update available bits
469:           countAvail -= n;
470:           bitsAvail <<= n;
471:         }
472:         assert(count == rectInfo.bitsPerSample);
473:         return value;
474:       };
475: 
476:       if (rectInfo.bitsPerSample == bitsPerSrcPixel) {
477:         // Fast path: bits per sample matches source pixel size
478:         loop(process_word);
479:       } else {
480:         // Slow path: bits per sample does not match source pixel size
481:         loop(process_bits);
482:       }
483:     }
484: 
485:     void invertColors() {
486:       uint8_t* data = image_.dataPtr<uint8_t>();
487:       for (size_t i = 0; i < image_.data.size(); ++i) {
488:         data[i] = ~data[i];
489:       }
490:     }
491:   };
492: 
493:   // TiffExporter implementation for Grayscale images ------------------------
494:   template <typename DstType, typename SrcType = DstType>
495:   class TiffExporterGray : public TiffExporter
496:   {
497:   public:
498:     // Callback for TiffCraft::load() function
499:     void operator()(
500:       const TiffImage::Header& header,
501:       const TiffImage::IFD& ifd,
502:       TiffImage::ImageData imageData) override
503:     {
504:       const int samplesPerPixel = requireSamplesPerPixel(ifd, 1);
505:       const int photometricInterpretation = requirePhotometricInterpretation(ifd, 1, std::less_equal<>());
506:       const int compression = requireCompression(ifd, 1);
507:       const int fillOrder = requireFillOrder(ifd, 1);
508: 
509:       const int bitsPerSample = getInt(ifd, Tag::BitsPerSample, 1);
510: 
511:       constexpr size_t maxDstValue = std::numeric_limits<DstType>::max();
512:       const size_t maxSrcValue = bitsPerSample < sizeof(size_t) * 8
513:         ? (size_t(1) << bitsPerSample) - 1 : std::numeric_limits<size_t>::max();
514: 
515:       const auto rectInfo = getRectInfo(ifd);
516: 
517:       // create the image and copy the pixel data
518:       image_ = Image::make<DstType, 1>(getWidth(ifd), getHeight(ifd));
519:       using UnaryOp = std::function<DstType(DstType)>;
520:       copyRectangles<SrcType,DstType,UnaryOp>(
521:         imageData, // source pixel data
522:         rectInfo,  // rectangle info
523:         1, // source image channels
524:         1, // source image planes
525:         header.equalsHostByteOrder(), // source data byte order
526:         [&](DstType value) -> DstType {
527:           return (value * maxDstValue) / maxSrcValue;
528:         }
529:       );
530: 
531:       if (photometricInterpretation == 0) { // WhiteIsZero
532:         invertColors();
533:       }
534:     }
535:   };
536: 
537:   // TiffExporter implementation for Palette-color images --------------------
538:   template <typename DstType, typename SrcType = DstType>
539:   class TiffExporterPalette : public TiffExporter
540:   {
541:   public:
542:     // Callback for TiffCraft::load() function
543:     void operator()(
544:       const TiffImage::Header& header,
545:       const TiffImage::IFD& ifd,
546:       TiffImage::ImageData imageData) override
547:     {
548:       const int samplesPerPixel = requireSamplesPerPixel(ifd, 1);
549:       const int photometricInterpretation = requirePhotometricInterpretation(ifd, 3);
550:       const int compression = requireCompression(ifd, 1);
551:       const int fillOrder = requireFillOrder(ifd, 1);
552: 
553:       const int bitsPerSample = getInt(ifd, Tag::BitsPerSample, 1);
554: 
555:       const auto numColors = (1 << bitsPerSample);
556:       const auto colorMap = getIntVec(ifd, Tag::ColorMap);
557:       if (3 * numColors > colorMap.size()) {
558:         throw std::runtime_error("Color map size does not match bits per sample");
559:       }
560:       const int chan[3] = { numColors * 0, numColors * 1, numColors * 2 };
561: 
562:       constexpr int bitsPerDstPixel = 8 * sizeof(DstType);
563: 
564:       const auto rectInfo = getRectInfo(ifd);
565: 
566:       // create the image and copy the pixel data
567:       image_ = Image::make<DstType, 3>(getWidth(ifd), getHeight(ifd));
568:       using UnaryOp = std::function<Rgb<DstType>(DstType)>;
569:       copyRectangles<SrcType,DstType,UnaryOp>(
570:         imageData, // source pixel data
571:         rectInfo,  // rectangle info
572:         1, // source image channels
573:         1, // source image planes
574:         header.equalsHostByteOrder(), // source data byte order
575:         [&](DstType value) -> Rgb<DstType> {
576:           return {
577:             static_cast<DstType>(colorMap[chan[0] + value] >> (16 - bitsPerDstPixel)),
578:             static_cast<DstType>(colorMap[chan[1] + value] >> (16 - bitsPerDstPixel)),
579:             static_cast<DstType>(colorMap[chan[2] + value] >> (16 - bitsPerDstPixel))
580:           };
581:         }
582:       );
583:     }
584:   };
585: 
586:   // TiffExporter implementation for RGB images ------------------------------
587:   template <typename DstType, typename SrcType = DstType>
588:   class TiffExporterRgb : public TiffExporter
589:   {
590:   public:
591:     // Callback for TiffCraft::load() function
592:     void operator()(
593:       const TiffImage::Header& header,
594:       const TiffImage::IFD& ifd,
595:       TiffImage::ImageData imageData) override
596:     {
597:       const int samplesPerPixel = requireSamplesPerPixel(ifd, 3);
598:       const int photometricInterpretation = requirePhotometricInterpretation(ifd, 2);
599:       const int compression = requireCompression(ifd, 1);
600: 
601:       const int planarConfiguration = requirePlanarConfiguration(ifd, -1,
602:         [](int value, int requiredValue) {
603:           return value == 1 || value == 2; // 1 for Contiguous, 2 for Planar
604:         });
605:       const bool isPlanar = (planarConfiguration == 2);
606: 
607:       const auto bitsPerSampleVec = getIntVec(ifd, Tag::BitsPerSample);
608:       if (bitsPerSampleVec.size() != 3) {
609:         throw std::runtime_error("Expected 3 bits per sample for RGB image");
610:       }
611: 
612:       const int bitsPerSample = bitsPerSampleVec.front();
613:       for (auto bits : bitsPerSampleVec) {
614:         if (bits != bitsPerSample) {
615:           throw std::runtime_error("Unsupported bits per sample for RGB image");
616:         }
617:       }
618: 
619:       constexpr size_t maxDstValue = std::numeric_limits<DstType>::max();
620:       const size_t maxSrcValue = bitsPerSample < sizeof(size_t) * 8
621:         ? (size_t(1) << bitsPerSample) - 1 : std::numeric_limits<size_t>::max();
622: 
623:       const auto rectInfo = getRectInfo(ifd);
624: 
625:       // create the image and copy the pixel data
626:       image_ = Image::make<DstType, 3>(getWidth(ifd), getHeight(ifd), isPlanar);
627:       using UnaryOp = std::function<DstType(DstType)>;
628:       copyRectangles<SrcType,DstType,UnaryOp>(
629:         imageData, // source pixel data
630:         rectInfo,  // rectangle info
631:         isPlanar ? 1 : samplesPerPixel, // source image channels
632:         isPlanar ? samplesPerPixel : 1, // source image planes
633:         header.equalsHostByteOrder(),   // source data byte order
634:         [&](DstType value) -> DstType {
635:           return (value * maxDstValue) / maxSrcValue;
636:         }
637:       );
638:     }
639:   };
640: 
641:   // TiffExporter implementation for all supported image types ---------------
642:   class TiffExporterAny : public TiffExporter
643:   {
644:     bool exported_ = false;
645:   public:
646:     // Callback for TiffCraft::load() function
647:     void operator()(
648:       const TiffImage::Header& header,
649:       const TiffImage::IFD& ifd,
650:       TiffImage::ImageData imageData) override
651:     {
652:       exported_ = false;
653:       const int photometricInterpretation = getInt(ifd, Tag::PhotometricInterpretation, 1);
654: 
655:       if (photometricInterpretation >= 0 && photometricInterpretation <= 1) {
656:         // grayscale image types
657:         const int bitsPerSample = getInt(ifd, Tag::BitsPerSample, 1);
658:         if (bitsPerSample <= 8) {
659:           tryToExport<TiffExporterGray<uint8_t>>(header, ifd, imageData);
660:         } else if (bitsPerSample <= 15) {
661:           tryToExport<TiffExporterGray<uint16_t,uint8_t>>(header, ifd, imageData);
662:         } else if (bitsPerSample == 16) {
663:           tryToExport<TiffExporterGray<uint16_t>>(header, ifd, imageData);
664:         } else if (bitsPerSample <= 31) {
665:           tryToExport<TiffExporterGray<uint32_t,uint8_t>>(header, ifd, imageData);
666:         } else if (bitsPerSample == 32) {
667:           tryToExport<TiffExporterGray<uint32_t>>(header, ifd, imageData);
668:         }
669:       } else if (photometricInterpretation == 2) {
670:         // RGB image types
671:         std::vector<int> bitsPerSampleVec = getIntVec(ifd, Tag::BitsPerSample);
672:         if (bitsPerSampleVec.size() > 0
673:           && std::any_of(bitsPerSampleVec.begin(), bitsPerSampleVec.end(),
674:             [&](int n) { return n != bitsPerSampleVec.front(); })) {
675:           throw std::runtime_error("Unsupported bits per sample for RGB image");
676:         }
677:         const int bitsPerSample = bitsPerSampleVec.empty() ? 1 : bitsPerSampleVec.front();
678:         if (bitsPerSample <= 8) {
679:           tryToExport<TiffExporterRgb<uint8_t>>(header, ifd, imageData);
680:         } else if (bitsPerSample <= 15) {
681:           tryToExport<TiffExporterRgb<uint16_t,uint8_t>>(header, ifd, imageData);
682:         } else if (bitsPerSample == 16) {
683:           tryToExport<TiffExporterRgb<uint16_t>>(header, ifd, imageData);
684:         } else if (bitsPerSample <= 31) {
685:           tryToExport<TiffExporterRgb<uint32_t,uint8_t>>(header, ifd, imageData);
686:         } else if (bitsPerSample == 32) {
687:           tryToExport<TiffExporterRgb<uint32_t>>(header, ifd, imageData);
688:         }
689:       } else if (photometricInterpretation == 3) {
690:         // palette-color image types
691:         const int bitsPerSample = getInt(ifd, Tag::BitsPerSample, 1);
692:         if (bitsPerSample <= 8) {
693:           tryToExport<TiffExporterPalette<uint8_t>>(header, ifd, imageData);
694:         } else if (bitsPerSample <= 16) {
695:           tryToExport<TiffExporterPalette<uint16_t>>(header, ifd, imageData);
696:         }
697:       }
698: 
699:       if (!exported_ || image_.dataSize() == 0)
700:       { // image was not exported
701:         throw FormatNotSupportedError("No exporter can handle this image");
702:       }
703:     }
704: 
705:     template <typename Exporter>
706:     void tryToExport(const TiffImage::Header& header,
707:                      const TiffImage::IFD& ifd,
708:                      TiffImage::ImageData imageData)
709:     {
710:       if (!exported_) {
711:         // Image has not been exported yet
712:         try {
713:           // Try with the provided exporter
714:           Exporter exporter;
715:           exporter(header, ifd, imageData);
716:           image_ = exporter.takeImage();
717:           exported_ = true;
718:         } catch (const FormatNotSupportedError&) {
719:           // Image format not supported by the current exporter, ignore
720:         }
721:       }
722:     }
723:   };
724: }

